var channels = [];
var lastResults = [];
async function postJson(url, body) {
var r = await fetch(url, {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify(body || {}),
});
if (!r.ok) throw new Error('HTTP ' + r.status);
return r.json();
}
function chAvatar(src) {
var img = document.createElement('img');
img.className = 'yt-ch-avatar';
img.alt = '';
img.loading = 'lazy';
img.src = src || '';
img.onerror = function () { this.style.visibility = 'hidden'; };
return img;
}
function chInfo(name, meta) {
var box = document.createElement('div');
box.className = 'yt-ch-info';
var n = document.createElement('div');
n.className = 'yt-ch-name';
n.textContent = name || '';
box.appendChild(n);
if (meta) {
var m = document.createElement('div');
m.className = 'yt-ch-meta';
m.textContent = meta;
box.appendChild(m);
}
return box;
}
function chBtn(text, action, id, cls) {
var b = document.createElement('button');
b.type = 'button';
b.className = 'yt-ch-btn' + (cls ? ' ' + cls : '');
b.textContent = text;
b.dataset.action = action;
b.dataset.id = id;
return b;
}
function renderSearchResults(list) {
lastResults = list || [];
var box = $('chResults');
box.innerHTML = '';
if (!lastResults.length) { box.style.display = 'none'; return; }
box.style.display = 'flex';
lastResults.forEach(function (c) {
var item = document.createElement('div');
item.className = 'yt-ch-item';
item.appendChild(chAvatar(c.avatar));
item.appendChild(chInfo(c.name, [c.subs, c.videos].filter(Boolean).join(' \xB7 ')));
var added = channels.some(function (x) { return x.id === c.id; });
var b = chBtn(added ? '\u5DF2\u52A0\u5165' : '\u52A0\u5165', 'add', c.id);
b.dataset.name = c.name || '';
b.dataset.avatar = c.avatar || '';
b.dataset.subs = c.subs || '';
b.disabled = added;
var act = document.createElement('div');
act.className = 'yt-ch-actions';
act.appendChild(b);
item.appendChild(act);
box.appendChild(item);
});
}
function renderChannels() {
var box = $('chList');
box.innerHTML = '';
$('chEmpty').style.display = channels.length ? 'none' : '';
channels.forEach(function (c, i) {
var item = document.createElement('div');
item.className = 'yt-ch-item';
item.appendChild(chAvatar(c.avatar));
item.appendChild(chInfo(c.name, c.subs));
var act = document.createElement('div');
act.className = 'yt-ch-actions';
if (i > 0) act.appendChild(chBtn('\u2191', 'move-up', c.id));
if (i < channels.length - 1) act.appendChild(chBtn('\u2193', 'move-down', c.id));
act.appendChild(chBtn('\u522A\u9664', 'remove', c.id, 'danger'));
item.appendChild(act);
box.appendChild(item);
});
}
async function loadChannels() {
try {
var d = await fetchJson('/website/youtube/api/channels');
channels = (d && d.list) || [];
} catch (e) {
channels = [];
}
renderChannels();
}
async function doChannelSearch() {
var q = $('chSearchInput').value.trim();
if (!q) { showToastSafe('\u8ACB\u8F38\u5165\u983B\u9053\u540D\u7A31'); return; }
var box = $('chResults');
box.style.display = 'flex';
box.innerHTML = '<div class="yt-tip">\u641C\u5C0B\u4E2D\u2026</div>';
try {
var d = await fetchJson('/website/youtube/api/channel/search?q=' + encodeURIComponent(q));
if (!d.ok) throw new Error(d.error || '');
if (!d.list.length) {
box.innerHTML = '<div class="yt-tip">\u6C92\u6709\u627E\u5230\u983B\u9053</div>';
lastResults = [];
return;
}
renderSearchResults(d.list);
} catch (e) {
box.innerHTML = '';
var err = document.createElement('div');
err.className = 'yt-tip';
err.textContent = '\u641C\u5C0B\u5931\u6557\uFF1A' + e.message;
box.appendChild(err);
}
}
async function channelAction(action, id, extra) {
try {
var body = { action: action, id: id };
if (extra) for (var k in extra) body[k] = extra[k];
var d = await postJson('/website/youtube/api/channels', body);
if (!d.ok) throw new Error(d.error || '\u64CD\u4F5C\u5931\u6557');
channels = d.list || [];
renderChannels();
renderSearchResults(lastResults);
showToastSafe(action === 'add' ? '\u5DF2\u52A0\u5165\u983B\u9053' : action === 'remove' ? '\u5DF2\u79FB\u9664\u983B\u9053' : '\u5DF2\u66F4\u65B0');
} catch (e) {
showToastSafe('\u64CD\u4F5C\u5931\u6557\uFF1A' + e.message);
}
}
async function onChannelClick(e) {
var b = e.target.closest('.yt-ch-btn');
if (!b || b.disabled) return;
var action = b.dataset.action;
var id = b.dataset.id;
if (action === 'add') {
await channelAction('add', id, {
channel: { id: id, name: b.dataset.name, avatar: b.dataset.avatar, subs: b.dataset.subs },
});
} else if (action === 'remove') {
var ch = channels.filter(function (x) { return x.id === id; })[0];
var ok = true;
try {
ok = await showConfirm('\u78BA\u5B9A\u79FB\u9664\u983B\u9053\u300C' + ((ch && ch.name) || '') + '\u300D\uFF1F', { title: '\u79FB\u9664\u983B\u9053', danger: true });
} catch (err) {
ok = window.confirm('\u78BA\u5B9A\u79FB\u9664\u983B\u9053\uFF1F');
}
if (ok) await channelAction('remove', id);
} else if (action === 'move-up') {
await channelAction('move', id, { dir: 'up' });
} else if (action === 'move-down') {
await channelAction('move', id, { dir: 'down' });
}
}
