// ---------- M3U8 \u64AD\u653E\u512A\u5316 ----------
var allSources = [];
var blacklistKeys = new Set();
function updateBlacklistCount() {
var el = $('m3u8BlacklistCount');
if (el) el.textContent = String(blacklistKeys.size);
}
function updateBlacklistAvailability() {
var section = $('m3u8BlacklistSection');
if (!section) return;
var search = $('m3u8BlacklistSearch');
var cleanOn = $('globalM3u8CleanToggle') && $('globalM3u8CleanToggle').checked;
var accelOn = $('globalM3u8AccelToggle') && $('globalM3u8AccelToggle').checked;
var enabled = Boolean(cleanOn || accelOn);
section.style.opacity = enabled ? '1' : '0.5';
section.style.pointerEvents = enabled ? 'auto' : 'none';
if (search) search.disabled = !enabled;
section.querySelectorAll('input[type="checkbox"]').forEach(function (cb) {
cb.disabled = !enabled;
});
var btnAll = $('blSelectAllBtn');
var btnClear = $('blClearAllBtn');
if (btnAll) btnAll.disabled = !enabled;
if (btnClear) btnClear.disabled = !enabled;
}
var blFilterMode = 'all'; // 'all' | 'checked'
function updateBlacklistFilterButtons() {
var btnAll = document.querySelector('#blFilterGroup [data-filter="all"]');
var btnChecked = document.querySelector('#blFilterGroup [data-filter="checked"]');
if (btnAll) {
btnAll.textContent = '\u5168\u90E8 (' + allSources.length + ')';
btnAll.classList.toggle('active', blFilterMode === 'all');
}
if (btnChecked) {
btnChecked.textContent = '\u50C5\u9ED1\u540D\u55AE (' + blacklistKeys.size + ')';
btnChecked.classList.toggle('active', blFilterMode === 'checked');
}
}
function resetBlacklistScroll() {
CatPaw.resetScroll('m3u8BlacklistList');
}
function renderBlacklistList(shouldResetScroll) {
var listEl = $('m3u8BlacklistList');
if (!listEl) return;
if (shouldResetScroll || listEl.scrollTop > 0) {
resetBlacklistScroll();
}
var q = (($('m3u8BlacklistSearch') && $('m3u8BlacklistSearch').value) || '').trim().toLowerCase();
var sources = allSources.filter(function (item) {
var isChecked = blacklistKeys.has(item.key);
if (blFilterMode === 'checked' && !isChecked) return false;
if (!q) return true;
return (item.name || '').toLowerCase().indexOf(q) >= 0 || (item.originalName || '').toLowerCase().indexOf(q) >= 0 || (item.key || '').toLowerCase().indexOf(q) >= 0;
});
if (!sources.length) {
var emptyText = allSources.length ? (blFilterMode === 'checked' ? '\u76EE\u524D\u7121\u9ED1\u540D\u55AE\u7AD9\u9EDE' : '\u7121\u7B26\u5408\u689D\u4EF6\u7684\u6E90') : '\u7AD9\u6E90\u5217\u8868\u8F09\u5165\u4E2D...';
listEl.innerHTML = '<div style="font-size:12.5px;color:var(--color-text-muted,#71737d);padding:14px 4px;text-align:center;">' + emptyText + '</div>';
updateBlacklistFilterButtons();
return;
}
listEl.innerHTML = sources
.map(function (item) {
var checked = blacklistKeys.has(item.key);
return '<label class="pb-bl-item' + (checked ? ' is-checked' : '') + '">' + '<input type="checkbox" data-blkey="' + esc(item.key) + '"' + (checked ? ' checked' : '') + ' />' + '<span class="pb-bl-name">' + esc(item.name || item.key) + '</span>' + '<span class="pb-bl-key">' + esc(item.key) + '</span>' + '</label>';
})
.join('');
updateBlacklistFilterButtons();
updateBlacklistAvailability();
}
async function saveBlacklist() {
try {
var resp = await fetch('/website/playback/m3u8-settings', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ blacklist: Array.from(blacklistKeys) }),
});
var res = await resp.json();
if (res.code !== 0) throw new Error(res.message || '\u5132\u5B58\u5931\u6557');
return true;
} catch (err) {
toast('\u9ED1\u540D\u55AE\u5132\u5B58\u5931\u6557: ' + err.message, 'error');
return false;
}
}
async function loadM3u8Settings() {
try {
var d = await fetchJson('/website/playback/m3u8-settings');
if (d.code === 0 && d.data) {
var cleanToggle = $('globalM3u8CleanToggle');
var accelToggle = $('globalM3u8AccelToggle');
if (cleanToggle) cleanToggle.checked = d.data.clean !== false;
if (accelToggle) accelToggle.checked = d.data.accel !== false;
if (Array.isArray(d.data.blacklist)) {
blacklistKeys = new Set(d.data.blacklist);
updateBlacklistCount();
}
}
} catch (e) {
console.warn('\u8F09\u5165\u64AD\u653E\u512A\u5316\u914D\u7F6E\u5931\u6557:', e);
}
renderBlacklistList();
updateBlacklistAvailability();
}
async function fetchAllSources() {
try {
var resp = await fetch('/website/sources', { headers: { Accept: 'application/json' } });
var result = await resp.json();
if (result.code === 0 && result.data) {
allSources = result.data.sources || [];
renderBlacklistList();
}
} catch (err) {
console.warn('\u8F09\u5165\u7AD9\u6E90\u5217\u8868\u5931\u6557:', err);
}
}
async function onToggleChange(kind, checked, el) {
updateBlacklistAvailability();
try {
var body = {};
body[kind] = checked;
var d = await fetchJson('/website/playback/m3u8-settings', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify(body),
});
if (d.code === 0) {
var msg = kind === 'clean' ? (checked ? '\u5DF2\u555F\u7528 M3U8 \u5EE3\u544A\u5207\u7247\u6E05\u6D17' : '\u5DF2\u95DC\u9589 M3U8 \u5EE3\u544A\u5207\u7247\u6E05\u6D17') : checked ? '\u5DF2\u555F\u7528 TS \u9810\u53D6\u52A0\u901F' : '\u5DF2\u95DC\u9589 TS \u9810\u53D6\u52A0\u901F';
toast(msg, 'success');
} else {
throw new Error(d.message);
}
} catch (err) {
toast('\u66F4\u65B0\u5931\u6557: ' + err.message, 'error');
el.checked = !checked;
updateBlacklistAvailability();
}
}
// ---------- \u7DB2\u76E4\u6383\u78BC\u767B\u5165 ----------
function renderQrImage(url) {
var box = $('qrBox');
box.innerHTML = '<img src="' + esc(url) + '" style="width:200px;height:200px;object-fit:contain;" alt="\u6383\u78BC\u767B\u5165" />';
box.style.display = 'flex';
}
function renderQr(text) {
var box = $('qrBox');
box.innerHTML = '';
try {
var qr = qrcode(0, 'M');
qr.addData(text);
qr.make();
box.innerHTML = qr.createSvgTag({ cellSize: 4.8, margin: 2 });
box.style.display = 'flex';
} catch (e) {
box.innerHTML = '<div style="color:#999;font-size:12px;">\u4E8C\u7DAD\u78BC\u751F\u6210\u5931\u6557</div>';
box.style.display = 'flex';
}
}
function qrSetMsg(msg) {
var el = $('qrLoginMsg');
if (el) el.textContent = msg || '';
}
function qrStop(silent) {
if (qrTimer) {
clearInterval(qrTimer);
qrTimer = null;
}
if (qrTask && !silent) {
fetchJson('/website/playback/login/cancel', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ taskId: qrTask.taskId }),
}).catch(function () {});
}
qrTask = null;
}
function qrClose() {
qrStop(false);
var dlg = $('qrLoginDialog');
try {
if (dlg && typeof dlg.close === 'function') dlg.close();
} catch (e) {}
}
async function qrPollOnce() {
var task = qrTask;
if (!task || qrPolling) return;
qrPolling = true;
try {
var d = await fetchJson('/website/playback/login/poll', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify({ provider: task.provider, taskId: task.taskId }),
});
if (qrTask !== task) return;
if (d.code !== 0) throw new Error(d.message || '\u8F2A\u8A62\u5931\u6557');
var r = d.data || {};
qrSetMsg(r.msg || '');
if (r.terminal) {
if (qrTimer) {
clearInterval(qrTimer);
qrTimer = null;
}
if (r.status === 'success' && (r.cookie || r.values)) {
var filled = 0;
if (r.values && typeof r.values === 'object') {
Object.keys(r.values).forEach(function (k) {
var parts = String(k).split('.');
var target = document.getElementById('f_' + parts[0] + '_' + parts[1]);
if (target && r.values[k]) {
target.value = r.values[k];
filled++;
}
});
} else if (r.cookie) {
var target = null;
if (task.cookieField) {
var parts = task.cookieField.split('.');
target = document.getElementById('f_' + parts[0] + '_' + parts[1]);
}
if (target) {
target.value = r.cookie;
filled++;
}
}
if (filled) {
toast('\u6383\u78BC\u6210\u529F\uFF0C\u5DF2\u81EA\u52D5\u586B\u5165\u8868\u55AE\uFF0C\u9EDE\u300C\u4FDD\u5B58\u4E26\u751F\u6548\u300D\u5B8C\u6210', 'success');
} else {
toast(r.msg || '\u6383\u78BC\u6210\u529F', 'success');
}
} else if (r.status === 'expired') {
toast('\u4E8C\u7DAD\u78BC\u5DF2\u904E\u671F\uFF0C\u8ACB\u91CD\u65B0\u751F\u6210', 'error');
} else {
toast(r.msg || '\u767B\u5165\u5931\u6557', 'error');
}
if (qrTask === task) qrTask = null;
}
} catch (e) {
if (qrTask !== task) return;
if (qrTimer) {
clearInterval(qrTimer);
qrTimer = null;
}
qrSetMsg('\u8F2A\u8A62\u7570\u5E38\uFF1A' + e.message);
qrTask = null;
} finally {
qrPolling = false;
}
}
async function qrStart(providerId) {
var provider = null;
loginProviders.forEach(function (p) {
if (p.id === providerId) provider = p;
});
if (!provider) {
toast('\u4E0D\u652F\u63F4\u7684\u767B\u5165\u65B9\u5F0F', 'error');
return;
}
qrStop(true);
$('qrLoginTitle').textContent = '\u6383\u78BC\u767B\u5165 ' + (provider.name || '');
qrSetMsg('\u6B63\u5728\u751F\u6210\u4E8C\u7DAD\u78BC\u2026');
$('qrBox').style.display = 'none';
$('qrBox').innerHTML = '';
var dlg = $('qrLoginDialog');
try {
if (dlg && typeof dlg.showModal === 'function') dlg.showModal();
else if (dlg) dlg.setAttribute('open', '');
} catch (e) {}
try {
var startBody = { provider: provider.id };
if (provider.id === 'ucToken') {
var didEl = document.getElementById('f_uc_device_id');
if (didEl && didEl.value) startBody.deviceId = didEl.value;
}
var d = await fetchJson('/website/playback/login/start', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify(startBody),
});
if (d.code !== 0) throw new Error(d.message || '\u767C\u8D77\u5931\u6557');
qrTask = { provider: provider.id, taskId: d.data.taskId, cookieField: provider.cookieField };
qrSetMsg(d.data.msg || '');
if (d.data.qrImage) renderQrImage(d.data.qrImage);
else renderQr(d.data.qrUrl);
if (qrTimer) clearInterval(qrTimer);
qrTimer = setInterval(qrPollOnce, 2000);
} catch (e) {
qrSetMsg('\u767C\u8D77\u5931\u6557\uFF1A' + e.message);
qrTask = null;
}
}
async function loadLoginProviders() {
try {
var d = await fetchJson('/website/playback/login/providers');
if (d.code === 0 && d.data) loginProviders = d.data.providers || [];
} catch (e) {
console.warn('\u8F09\u5165\u6383\u78BC\u767B\u5165\u65B9\u5F0F\u5931\u6557:', e);
}
}
